inline constexpr int N = 48;

// Sorted by iso3, so this is a binary search. Returns nullptr for an
// unknown or empty code - the caller draws NO flag (decision 20).
inline const Flag *find(const char *iso3) {
  if (iso3 == nullptr || iso3[0] == '\0') return nullptr;
  int lo = 0, hi = N - 1;
  while (lo <= hi) {
    const int mid = (lo + hi) / 2;
    const int cmp = std::strcmp(iso3, F[mid].iso3);
    if (cmp == 0) return &F[mid];
    if (cmp < 0) hi = mid - 1; else lo = mid + 1;
  }
  return nullptr;
}

